--
-- Table structure for table `inventario_materiales`
--

DROP TABLE IF EXISTS `inventario_materiales`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inventario_materiales` (
  `id` int NOT NULL AUTO_INCREMENT,
  `codigo` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombreMaterial` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `cantidadDisponible` int NOT NULL DEFAULT '0',
  `stockMinimo` int NOT NULL DEFAULT '5',
  `fechaUltimaActualizacion` date NOT NULL,
  `categoria` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `area` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tipo` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `marca` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `numeroSerie` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL ON UPDATE CURRENT_TIMESTAMP(3),
  `fungible` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'Fungible',
  `pertenece` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'Iglesia',
  `fotografia` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `inventario_materiales_codigo_key` (`codigo`)
) ENGINE=InnoDB AUTO_INCREMENT=112 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

