  `anio` int NOT NULL,
  `infanteId` int NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL ON UPDATE CURRENT_TIMESTAMP(3),
  `entregadoPorId` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `regalos_infanteId_anio_idx` (`infanteId`,`anio`),
  KEY `regalos_entregadoPorId_idx` (`entregadoPorId`),
